# Summarize each kept pair: object heights, marker position, selected output row
for i,pair in enumerate(pairs):
 g=pair['input']; o=pair['output']
 seps=[(r,row[0]) for r,row in enumerate(g) if row[0]!=0 and len(set(row))==1]
 slots=[]; mc=None; mr=None
 for j,(r,c) in enumerate(seps):
  if c==9: continue
  end=seps[j+1][0] if j+1<len(seps) else len(g)
  for rr in range(r,end):
   for cc in range(21):
    if g[rr][cc]==5: mc,mr=cc,rr
  cells=[rr for rr in range(r+1,end) for cc in range(21) if g[rr][cc]==c]
  slots.append((c, max(cells)-min(cells)+1 if cells else None))
 sel=[r for r,row in enumerate(o) if row[4]==5][0]
 print(i, slots, 'marker',mr,mc,'->',sel)
